-- Economics Gen2 T3 Practice rebalancing: 20 easy / 30 medium / 20 hard.
-- Original questions never deleted; originals with historical references remain resolvable.
-- New question versions carry their own complete trilingual content and per-option diagnostics.
-- Preconditions and postconditions are enforced transactionally. Run controlled QA transaction first.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '90s';
DO $reb$
DECLARE
  payload jsonb := '[{"ref":"EC9708:G2:EC9708-G2-T3-P-001","d":"hard","sec":210,"k":"B","en":"A small country faces a fixed world price of $30. Its domestic demand is Qd = 200 − 2P and domestic supply is Qs = 20 + P. A tariff of $10 per imported unit raises the domestic price to $40. What are imports after the tariff and government tariff revenue?","ru":"Малая страна покупает товар по неизменной мировой цене $30. Внутренний спрос Qd = 200 − 2P, предложение Qs = 20 + P. Пошлина $10 на импортную единицу повышает внутреннюю цену до $40. Каковы импорт после пошлины и доход бюджета от неё?","uz":"Kichik mamlakatda jahon narxi o‘zgarmas $30. Ichki talab Qd = 200 − 2P, taklif Qs = 20 + P. Har import birligiga $10 boj ichki narxni $40 ga oshiradi. Bojdan keyingi import hajmi va davlat boj daromadi qancha?","options_en":["80 units; $800","60 units; $600","40 units; $400","90 units; $900"],"options_ru":["80 единиц; $800","60 единиц; $600","40 единиц; $400","90 единиц; $900"],"options_uz":["80 birlik; $800","60 birlik; $600","40 birlik; $400","90 birlik; $900"],"why":["At P = 40 demand is 120 and domestic supply 60, so imports are 60. Revenue = 60 × $10 = $600.","При P = 40 спрос составляет 120, внутреннее предложение — 60, импорт — 60. Доход бюджета 60 × $10 = $600.","P = 40 da talab 120, ichki taklif 60, import 60. Boj daromadi 60 × $10 = $600."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-002","d":"hard","sec":195,"k":"D","en":"A country''s export and import price indices are 120 and 150. Next year export prices rise by 10% and import prices by 5%, measured from those index levels. Approximately how does the terms-of-trade index change?","ru":"Индексы экспортных и импортных цен страны равны 120 и 150. На следующий год цены экспорта растут на 10%, импорта — на 5% относительно указанных уровней. Как примерно изменится индекс условий торговли?","uz":"Mamlakat eksport va import narx indekslari 120 va 150. Keyingi yil eksport narxlari shu darajadan 10%, import narxlari esa 5% oshadi. Savdo shartlari indeksi taxminan qanday o‘zgaradi?","options_en":["From 80 to 76.2; deterioration","From 125 to 130.9; improvement","From 80 to 88.0; improvement","From 80 to 83.8; improvement"],"options_ru":["С 80 до 76,2; ухудшение","Со 125 до 130,9; улучшение","С 80 до 88,0; улучшение","С 80 до 83,8; улучшение"],"options_uz":["80 dan 76,2 ga; yomonlashish","125 dan 130,9 ga; yaxshilanish","80 dan 88,0 ga; yaxshilanish","80 dan 83,8 ga; yaxshilanish"],"why":["Initially ToT = 120/150 × 100 = 80. Afterwards it is 132/157.5 × 100 ≈ 83.8: an improvement.","Изначально индекс 120/150 × 100 = 80. Затем 132/157,5 × 100 ≈ 83,8: условия торговли улучшились.","Dastlab indeks 120/150 × 100 = 80. Keyin 132/157,5 × 100 ≈ 83,8; savdo shartlari yaxshilanadi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-003","d":"hard","sec":190,"k":"C","en":"An exporter initially sells 10,000 tonnes abroad at $100 per tonne. Its export price falls to $80 but the volume exported grows to 12,000 tonnes. Import prices do not change. By what percentages do its export price and total export receipts change?","ru":"Экспортёр первоначально продаёт за рубеж 10 000 тонн по $100 за тонну. Цена падает до $80, но объём экспорта увеличивается до 12 000 тонн. Цены импорта неизменны. На сколько процентов меняются экспортная цена и общая экспортная выручка?","uz":"Eksportchi dastlab chetga 10 000 tonnani bir tonnasini $100 dan sotadi. Eksport narxi $80 ga tushadi, hajm esa 12 000 tonnaga oshadi. Import narxlari o‘zgarmaydi. Eksport narxi va jami eksport tushumi necha foizga o‘zgaradi?","options_en":["Price −20%; receipts +20%","Price −20%; receipts −20%","Price −20%; receipts −4%","Price +20%; receipts −4%"],"options_ru":["Цена −20%; выручка +20%","Цена −20%; выручка −20%","Цена −20%; выручка −4%","Цена +20%; выручка −4%"],"options_uz":["Narx −20%; tushum +20%","Narx −20%; tushum −20%","Narx −20%; tushum −4%","Narx +20%; tushum −4%"],"why":["Price falls 20%. Receipts change from $1,000,000 to $960,000, a decline of 4%; volume growth does not fully offset the price decline.","Цена падает на 20%. Выручка уменьшается с $1 000 000 до $960 000, то есть на 4%; рост объёма не компенсирует падение цены.","Narx 20% tushadi. Tushum $1 000 000 dan $960 000 ga, ya’ni 4% ga kamayadi; hajm o‘sishi narx pasayishini to‘liq qoplamaydi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-005","d":"hard","sec":190,"k":"A","en":"Over one year nominal GDP rises by 12%, the GDP deflator rises by 8%, and population rises by 2%. Using exact index ratios rather than subtracting percentage points, approximately how much does real GDP per person grow?","ru":"За год номинальный ВВП вырос на 12%, дефлятор ВВП — на 8%, население — на 2%. Используя точные отношения индексов, а не вычитание процентных пунктов, найдите приблизительный рост реального ВВП на человека.","uz":"Bir yilda nominal YaIM 12% ga, YaIM deflyatori 8% ga, aholi 2% ga o‘sdi. Foiz punktlarini ayirish o‘rniga indekslarning aniq nisbatlarini qo‘llab, jon boshiga real YaIM o‘sishini toping.","options_en":["+1.67%","+2.00%","+3.70%","+6.00%"],"options_ru":["+1.67%","+2.00%","+3.70%","+6.00%"],"options_uz":["+1.67%","+2.00%","+3.70%","+6.00%"],"why":["The real per-person factor is (1.12/1.08)/1.02 ≈ 1.0167, or growth of about 1.67%.","Индекс реального ВВП на человека (1,12/1,08)/1,02 ≈ 1,0167; прирост около 1,67%.","Jon boshiga real YaIM koeffitsienti (1,12/1,08)/1,02 ≈ 1,0167; o‘sish taxminan 1,67%."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-006","d":"hard","sec":175,"k":"B","en":"An importer must pay a foreign supplier US$24,000. Initially US$1 costs 12,000 local currency units; later it costs 11,500. How has the importer''s local-currency bill changed, and which movement of the local currency explains it?","ru":"Импортёр должен иностранному поставщику $24 000. Первоначально $1 стоил 12 000 единиц местной валюты, позднее — 11 500. Как изменилась сумма платежа в местной валюте и каким изменением курса это объясняется?","uz":"Importchi xorijiy yetkazib beruvchiga $24 000 to‘lashi kerak. Dastlab $1 = 12 000 mahalliy pul birligi, keyin $1 = 11 500. Mahalliy valyutadagi to‘lov qanchaga o‘zgardi va bunga qanday kurs o‘zgarishi sabab bo‘ldi?","options_en":["Increased by 12 million; depreciation","Decreased by 12 million; appreciation","Decreased by 500,000; depreciation","Increased by 24 million; appreciation"],"options_ru":["Платёж вырос на 12 млн; обесценение","Платёж снизился на 12 млн; укрепление","Платёж снизился на 500 000; обесценение","Платёж вырос на 24 млн; укрепление"],"options_uz":["To‘lov 12 mln ga oshdi; qadrsizlanish","To‘lov 12 mln ga kamaydi; qadrlanish","To‘lov 500 000 ga kamaydi; qadrsizlanish","To‘lov 24 mln ga oshdi; qadrlanish"],"why":["Initially the bill is 24,000 × 12,000 = 288m local units; later 24,000 × 11,500 = 276m. It falls by 12m because local currency appreciates.","Первоначально платёж 288 млн единиц, затем 276 млн. Снижение на 12 млн вызвано укреплением местной валюты.","Dastlab to‘lov 288 mln birlik, keyin 276 mln. 12 mln ga kamayish mahalliy valyuta qadrlanganini bildiradi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-008","d":"hard","sec":205,"k":"D","en":"Government debt starts at $900m, and GDP is $1,800m. In each of the next two years, a $30m budget deficit is financed entirely through borrowing. At the end of year two, GDP is $1,980m. What happens to the debt level and the debt-to-GDP ratio?","ru":"Государственный долг первоначально $900 млн при ВВП $1 800 млн. В каждом из следующих двух лет дефицит бюджета $30 млн полностью финансируется заимствованиями. В конце второго года ВВП $1 980 млн. Как изменятся сумма долга и отношение долга к ВВП?","uz":"Davlat qarzi dastlab $900 mln, YaIM $1 800 mln. Keyingi ikki yilning har birida $30 mln budjet taqchilligi to‘liq qarz bilan qoplanadi. Ikkinchi yil oxirida YaIM $1 980 mln. Qarz summasi va qarz/YaIM nisbati qanday o‘zgaradi?","options_en":["Debt rises to $960m; ratio rises to 53.3%","Debt stays $900m; ratio falls to 45.5%","Debt falls to $840m; ratio falls to 42.4%","Debt rises to $960m; ratio falls from 50% to about 48.5%"],"options_ru":["Долг $960 млн; доля выросла до 53,3%","Долг $900 млн; доля снизилась до 45,5%","Долг $840 млн; доля снизилась до 42,4%","Долг $960 млн; доля снизилась с 50% примерно до 48,5%"],"options_uz":["Qarz $960 mln; ulush 53,3% gacha oshdi","Qarz $900 mln; ulush 45,5% ga tushdi","Qarz $840 mln; ulush 42,4% ga tushdi","Qarz $960 mln; ulush 50% dan taxminan 48,5% ga tushdi"],"why":["Debt rises by $60m to $960m. Initially debt/GDP = 900/1800 = 50%; finally 960/1980 ≈ 48.5%.","Долг увеличивается на $60 млн до $960 млн. Доля к ВВП сначала 900/1800 = 50%, в конце 960/1980 ≈ 48,5%.","Qarz $60 mln ga oshib $960 mln bo‘ladi. Dastlab qarz/YaIM 50%, oxirida 960/1980 ≈ 48,5%."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-010","d":"hard","sec":175,"k":"B","en":"Three households value a community flood barrier at $70, $40 and $30 respectively. The barrier costs $110 and provides protection to all three even if one refuses to contribute. What is its net social benefit, and what financing problem can still arise?","ru":"Три домохозяйства оценивают общую защитную дамбу в $70, $40 и $30 соответственно. Дамба стоит $110 и защищает всех троих, даже если кто-то отказывается платить. Какова чистая общественная выгода и какая проблема финансирования возможна?","uz":"Uch xonadon umumiy toshqin to‘sig‘ini $70, $40 va $30 ga baholaydi. To‘siq $110 turadi va biror xonadon to‘lashdan bosh tortsa ham, uchalasini himoya qiladi. Sof ijtimoiy foyda qancha va qanday moliyalashtirish muammosi yuz berishi mumkin?","options_en":["−$30; excess private supply","+$30; free riding may prevent voluntary funding","+$140; voluntary provision is guaranteed","+$110; the project cannot be publicly funded"],"options_ru":["−$30; избыточное частное предложение","+$30; безбилетники могут сорвать добровольное финансирование","+$140; добровольное обеспечение гарантировано","+$110; бюджетное финансирование невозможно"],"options_uz":["−$30; ortiqcha xususiy taklif","+$30; tekin foydalanish ixtiyoriy moliyalashtirishga to‘sqinlik qilishi mumkin","+$140; ixtiyoriy ta’minot kafolatlangan","+$110; davlat moliyalashtirishi mumkin emas"],"why":["Benefits total $140 against cost $110, yielding net benefit $30. Non-excludable benefits can induce free riding and underfunding.","Суммарная выгода $140 минус стоимость $110 даёт $30. Неисключаемость защиты порождает проблему безбилетника и риск недофинансирования.","Jami foyda $140, xarajat $110, sof foyda $30. Foydadan chetlatib bo‘lmasligi tekin foydalanish va mablag‘ yetishmasligi xavfini tug‘diradi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-015","d":"hard","sec":190,"k":"C","en":"A firm''s hourly wage rises from $20 to $22 following training, while output per labour-hour rises from 5 units to 8 units. Ignoring other costs, by what percentage does wage cost per unit change, and what supply-side implication follows?","ru":"После обучения почасовая оплата на предприятии повышается с $20 до $22, а производительность — с 5 до 8 изделий на человеко-час. Игнорируя остальные издержки, на сколько процентов изменятся затраты на оплату труда в расчёте на изделие и каков эффект для предложения?","uz":"O‘qitishdan so‘ng korxonada soatlik ish haqi $20 dan $22 ga, har ishchi-soatdagi ishlab chiqarish 5 tadan 8 taga oshadi. Boshqa xarajatlarni hisobga olmasdan, birlik uchun ish haqi xarajati necha foizga o‘zgaradi va taklifga qanday ta’sir qiladi?","options_en":["Rises by 10%; supply decreases","Falls by 12.5%; capacity necessarily falls","Falls by 31.25%; greater cost competitiveness is possible","Rises by 60%; higher unit costs restrict supply"],"options_ru":["Растут на 10%; предложение сокращается","Падают на 12,5%; потенциал обязательно снижается","Падают на 31,25%; конкурентоспособность может повыситься","Растут на 60%; рост издержек ограничивает предложение"],"options_uz":["10% ga oshadi; taklif kamayadi","12,5% ga kamayadi; salohiyat albatta pasayadi","31,25% ga kamayadi; raqobatbardoshlik oshishi mumkin","60% ga oshadi; xarajat taklifni cheklaydi"],"why":["Initial wage cost per unit = 20/5 = $4; new cost = 22/8 = $2.75. Reduction = 1.25/4 = 31.25%, supporting supply-side competitiveness.","Первоначально $20/5 = $4 за изделие, затем $22/8 = $2,75. Снижение $1,25/$4 = 31,25% может повысить конкурентоспособность предложения.","Dastlab birlik xarajati 20/5 = $4, keyin 22/8 = $2,75. Pasayish 1,25/4 = 31,25%; taklif raqobatbardoshligi yaxshilanishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-017","d":"hard","sec":205,"k":"C","en":"In one hour, Country A can make 4 bags of grain or 2 metres of cloth; Country B can make 3 bags of grain or 3 metres of cloth. Which specialisation and trade rate of 1 metre of cloth for grain could benefit both under constant opportunity costs?","ru":"За час страна A выпускает 4 мешка зерна или 2 метра ткани; страна B — 3 мешка зерна или 3 метра ткани. Какое распределение специализации и обмен 1 метра ткани на зерно могут быть взаимовыгодными при постоянных альтернативных издержках?","uz":"Bir soatda A mamlakat 4 qop don yoki 2 metr mato, B mamlakat esa 3 qop don yoki 3 metr mato ishlab chiqaradi. Doimiy muqobil xarajatlarda qaysi ixtisoslashuv va 1 metr matoning donga ayirboshlash nisbati ikkalasiga foydali bo‘lishi mumkin?","options_en":["A cloth, B grain; 3 bags per metre","A grain, B cloth; 3 bags per metre","A grain, B cloth; 1.5 bags per metre","A cloth, B grain; 1 bag per metre"],"options_ru":["A — ткань, B — зерно; 3 мешка за метр","A — зерно, B — ткань; 3 мешка за метр","A — зерно, B — ткань; 1,5 мешка за метр","A — ткань, B — зерно; 1 мешок за метр"],"options_uz":["A — mato, B — don; 3 qop/metr","A — don, B — mato; 3 qop/metr","A — don, B — mato; 1,5 qop/metr","A — mato, B — don; 1 qop/metr"],"why":["A''s cost of 1 m cloth is 2 bags of grain; B''s is 1 bag. B should specialise in cloth, A in grain. Trading at 1.5 bags per metre lies between their opportunity costs.","В A метр ткани стоит 2 мешка зерна, в B — 1 мешок. B специализируется на ткани, A — на зерне. Курс 1,5 мешка за метр лежит между альтернативными издержками.","A da 1 metr mato 2 qop don, B da 1 qop don turadi. B matoga, A donga ixtisoslashadi; 1,5 qop/metr ikkala muqobil xarajat orasida."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-020","d":"hard","sec":180,"k":"A","en":"An economy initially has AD: Qd = 200 − 2P and SRAS: Qs = 40 + 2P. An interest-rate cut raises aggregate demand to Qd = 240 − 2P without shifting SRAS. What are the changes in equilibrium price level and real output?","ru":"Первоначально в экономике AD: Qd = 200 − 2P, SRAS: Qs = 40 + 2P. Снижение процентной ставки сдвигает AD к Qd = 240 − 2P при неизменном SRAS. Как изменятся равновесные уровень цен и реальный выпуск?","uz":"Iqtisodiyotda dastlab AD: Qd = 200 − 2P va SRAS: Qs = 40 + 2P. Foiz stavkasi pasayib, AD Qd = 240 − 2P ga siljiydi, SRAS o‘zgarmaydi. Muvozanat narx darajasi va real ishlab chiqarish qanchaga o‘zgaradi?","options_en":["Price +10, output +20","Price −10, output +20","Price +20, output +10","Price unchanged, output +40"],"options_ru":["Уровень цен +10; выпуск +20","Уровень цен −10; выпуск +20","Уровень цен +20; выпуск +10","Уровень цен не меняется; выпуск +40"],"options_uz":["Narx darajasi +10; ishlab chiqarish +20","Narx darajasi −10; ishlab chiqarish +20","Narx darajasi +20; ishlab chiqarish +10","Narx darajasi o‘zgarmaydi; ishlab chiqarish +40"],"why":["Initially 200−2P = 40+2P gives P = 40, Q = 120. Afterwards 240−2P = 40+2P gives P = 50, Q = 140; changes +10 and +20.","Сначала P = 40, Q = 120; после сдвига P = 50, Q = 140. Уровень цен +10, выпуск +20.","Dastlab P = 40, Q = 120; keyin P = 50, Q = 140. Narx +10, ishlab chiqarish +20."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-022","d":"hard","sec":185,"k":"C","en":"A country initially has 4.5 million employed and 0.5 million actively unemployed people. During recession, 0.2 million unemployed people stop seeking jobs and leave the labour force; no one gains employment. What happens to the measured unemployment rate?","ru":"В стране первоначально 4,5 млн занятых и 0,5 млн активно ищущих работу безработных. Во время рецессии 0,2 млн безработных прекращают поиски и выходят из рабочей силы; новых рабочих мест не возникает. Как меняется измеряемый уровень безработицы?","uz":"Mamlakatda dastlab 4,5 mln band va faol ish qidirayotgan 0,5 mln ishsiz bor. Tanazzulda 0,2 mln ishsiz ish qidirishni to‘xtatib ishchi kuchidan chiqadi; hech kim ishga joylashmaydi. O‘lchanadigan ishsizlik darajasi qanday o‘zgaradi?","options_en":["Rises from 10% to 14%","Remains 10%, since employment is unchanged","Falls from 10% to 6.25%, despite unchanged employment","Falls from 10% to 4%, because 0.2 million gained jobs"],"options_ru":["Растёт с 10% до 14%","Остаётся 10%, поскольку занятость неизменна","Падает с 10% до 6,25% при неизменной занятости","Падает с 10% до 4%, потому что 0,2 млн устроились на работу"],"options_uz":["10% dan 14% ga oshadi","Bandlik o‘zgarmagani uchun 10% bo‘lib qoladi","Bandlik o‘zgarmasa ham 10% dan 6,25% ga tushadi","0,2 mln ishga joylashgani uchun 10% dan 4% ga tushadi"],"why":["Initially 0.5/(4.5+0.5)=10%; after leaving, 0.3/(4.5+0.3)=6.25%. This is a statistical fall, not job creation.","Изначально 0,5/(4,5+0,5)=10%; после ухода ищущих работу 0,3/(4,5+0,3)=6,25%. Снижение показателя не означает создание рабочих мест.","Dastlab 0,5/(4,5+0,5)=10%; keyin 0,3/(4,5+0,3)=6,25%. Ko‘rsatkich pasayishi yangi ish o‘rinlari yaratilganini bildirmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-023","d":"hard","sec":175,"k":"B","en":"Foreign-bond purchases increase the supply of domestic currency in a floating FX market. The quote moves from 12 to 14 domestic units per foreign unit. An importer must pay 25,000 foreign units. Approximately what is the change in its domestic-currency payment, and what happened to the domestic currency?","ru":"Покупки иностранных облигаций увеличивают предложение национальной валюты на плавающем валютном рынке. Курс меняется с 12 до 14 единиц местной валюты за иностранную. Импортёр должен заплатить 25 000 иностранных единиц. Как примерно изменится платёж в местной валюте и что произошло с её курсом?","uz":"Xorijiy obligatsiyalar xaridi suzuvchi valuta bozorida mahalliy valuta taklifini oshiradi. Kurs bir xorijiy birlik uchun 12 dan 14 mahalliy birlikka o‘zgaradi. Importchi 25 000 xorijiy birlik to‘laydi. Mahalliy valutadagi to‘lov taxminan qanday o‘zgaradi va valuta kursiga nima bo‘ladi?","options_en":["Payment falls by 50,000 (about 16.7%); currency appreciates","Payment rises by 50,000 (about 16.7%); currency depreciates","Payment rises by 25,000 (about 8.3%); currency appreciates","Payment is unchanged; currency depreciates"],"options_ru":["Платёж падает на 50 000 (≈16,7%); валюта укрепляется","Платёж растёт на 50 000 (≈16,7%); валюта ослабевает","Платёж растёт на 25 000 (≈8,3%); валюта укрепляется","Платёж неизменен; валюта ослабевает"],"options_uz":["To‘lov 50 000 ga (≈16,7%) kamayadi; valuta qadrlanadi","To‘lov 50 000 ga (≈16,7%) oshadi; valuta qadrsizlanadi","To‘lov 25 000 ga (≈8,3%) oshadi; valuta qadrlanadi","To‘lov o‘zgarmaydi; valuta qadrsizlanadi"],"why":["The bill rises from 25,000×12=300,000 to 25,000×14=350,000 domestic units, an increase of 50,000/300,000≈16.7%. The domestic currency depreciates.","Платёж растёт с 25 000×12=300 000 до 25 000×14=350 000, прирост 50 000/300 000≈16,7%. Местная валюта ослабевает.","To‘lov 25 000×12=300 000 dan 25 000×14=350 000 ga oshadi: 50 000/300 000≈16,7%. Mahalliy valuta qadrsizlanadi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-027","d":"hard","sec":200,"k":"D","en":"Tradable import licences permit 800 tonnes of rice. Licensed importers pay $70 per tonne abroad and sell for $110 domestically. The government auctions every licence for $25 per tonne. Ignoring other costs, what are total government auction receipts and the importers'' remaining quota rent?","ru":"Перепродаваемые лицензии разрешают ввоз 800 тонн риса. Импортёры покупают его за рубежом по $70 за тонну и продают внутри страны по $110. Государство продаёт все лицензии на аукционе по $25 на тонну. Без других издержек найдите доход бюджета от аукциона и оставшуюся квотную ренту импортёров.","uz":"Sotilishi mumkin bo‘lgan import litsenziyalari 800 tonna guruchga ruxsat beradi. Importchilar chetda tonnasini $70 ga olib, ichkarida $110 ga sotadi. Davlat barcha litsenziyalarni tonnasiga $25 dan auksionda sotadi. Boshqa xarajatlarsiz davlat auksion daromadi va importchilarda qolgan kvota rentasi qancha?","options_en":["Government $32,000; importers $0","Government $12,000; importers $20,000","Government $20,000; importers $32,000","Government $20,000; importers $12,000"],"options_ru":["Бюджет $32 000; импортёры $0","Бюджет $12 000; импортёры $20 000","Бюджет $20 000; импортёры $32 000","Бюджет $20 000; импортёры $12 000"],"options_uz":["Davlat $32 000; importchilar $0","Davlat $12 000; importchilar $20 000","Davlat $20 000; importchilar $32 000","Davlat $20 000; importchilar $12 000"],"why":["Gross quota rent = (110−70)×800=$32,000. Auction revenue =25×800=$20,000. Importers retain $12,000.","Валовая квотная рента (110−70)×800=$32 000. Доход бюджета 25×800=$20 000. Импортёрам остаётся $12 000.","Yalpi kvota rentasi (110−70)×800=$32 000. Auksion tushumi 25×800=$20 000. Importchilarda $12 000 qoladi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-028","d":"hard","sec":175,"k":"A","en":"Country Z bans commercial imports from Country A but permits identical inputs from B. A domestic manufacturer previously bought 1,200 imported input units from A at $35 each; it must now pay B $42 each. It sells 1,200 finished units at $60 per unit, with other variable costs of $10 per finished unit. Ignoring fixed costs, which policy and profit change follow?","ru":"Страна Z запрещает коммерческий импорт из страны A, но разрешает те же комплектующие из B. Предприятие раньше покупало 1 200 единиц из A по $35, теперь вынуждено брать из B по $42. Оно продаёт 1 200 готовых изделий по $60, прочие переменные затраты — $10 на изделие. Игнорируя постоянные затраты, определите политику и изменение прибыли.","uz":"Z mamlakati A dan tijoriy importni taqiqlaydi, ammo B dan ayni xomashyoni olishga ruxsat beradi. Mahalliy firma ilgari 1200 birlikni A dan $35 ga, endi B dan $42 ga oladi. Firma 1200 tayyor mahsulotni $60 dan sotadi, boshqa o‘zgaruvchi xarajat har biriga $10. Doimiy xarajatsiz siyosat va foyda qanday o‘zgaradi?","options_en":["Targeted embargo; operating profit falls from $18,000 to $9,600","General import tariff; operating profit falls from $18,000 to $9,600","Targeted embargo; operating profit rises from $18,000 to $26,400","Import quota; operating profit stays at $18,000"],"options_ru":["Адресное эмбарго; операционная прибыль падает с $18 000 до $9 600","Общая пошлина; операционная прибыль падает с $18 000 до $9 600","Адресное эмбарго; операционная прибыль растёт с $18 000 до $26 400","Импортная квота; операционная прибыль остаётся $18 000"],"options_uz":["Maqsadli embargo; operatsion foyda $18 000 dan $9 600 ga kamayadi","Umumiy import boji; operatsion foyda $18 000 dan $9 600 ga kamayadi","Maqsadli embargo; operatsion foyda $18 000 dan $26 400 ga oshadi","Import kvotasi; operatsion foyda $18 000 bo‘lib qoladi"],"why":["A source-specific ban is an embargo. Initial profit per unit = $60−$35−$10=$15, total $18,000; new profit per unit = $60−$42−$10=$8, total $9,600.","Запрет торговли с определённой страной — эмбарго. Раньше прибыль на единицу $60−$35−$10=$15, всего $18 000; теперь $60−$42−$10=$8, всего $9 600.","Muayyan mamlakatdan import taqiqi — embargo. Dastlab birlik foyda $60−$35−$10=$15, jami $18 000; endi $60−$42−$10=$8, jami $9 600."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-031","d":"hard","sec":190,"k":"B","en":"A country has a $20bn goods-trade deficit and imports services worth $35bn but exports services worth $50bn. Net primary income is +$3bn and net secondary income is −$2bn. What is its current-account balance?","ru":"В стране дефицит торговли товарами $20 млрд; импорт услуг $35 млрд, экспорт услуг $50 млрд. Сальдо первичных доходов +$3 млрд, вторичных доходов −$2 млрд. Найдите сальдо текущего счёта.","uz":"Mamlakatda tovar savdosi taqchilligi $20 mlrd; xizmat importi $35 mlrd, eksporti $50 mlrd. Sof birlamchi daromad +$3 mlrd, ikkilamchi daromad −$2 mlrd. Joriy hisob balansi qancha?","options_en":["+$4bn","−$4bn","−$9bn","+$31bn"],"options_ru":["+4 млрд долларов","−4 млрд долларов","−9 млрд долларов","+31 млрд долларов"],"options_uz":["+4 mlrd dollar","−4 mlrd dollar","−9 mlrd dollar","+31 mlrd dollar"],"why":["Current account = −20 + (50−35) +3−2 = −4 billion.","Текущий счёт = −20 + (50−35) +3−2 = −4 млрд долларов.","Joriy hisob = −20 + (50−35) +3−2 = −4 mlrd dollar."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-038","d":"hard","sec":190,"k":"A","en":"A country''s service exports are $90m and service imports $125m. Its goods balance is +$50m, net primary income is −$10m and net secondary income is +$2m. What are its services balance and overall current-account balance?","ru":"Страна экспортирует услуг на $90 млн и импортирует на $125 млн. Баланс товаров +$50 млн, сальдо первичных доходов −$10 млн, вторичных доходов +$2 млн. Каковы сальдо услуг и всего текущего счёта?","uz":"Mamlakat xizmatlarni $90 mln eksport, $125 mln import qiladi. Tovar balansi +$50 mln, sof birlamchi daromad −$10 mln, ikkilamchi daromad +$2 mln. Xizmatlar va umumiy joriy hisob balansi qanday?","options_en":["Services −$35m; current account +$7m","Services +$35m; current account +$77m","Services −$35m; current account −$7m","Services −$215m; current account −$173m"],"options_ru":["Услуги −$35 млн; текущий счёт +$7 млн","Услуги +$35 млн; текущий счёт +$77 млн","Услуги −$35 млн; текущий счёт −$7 млн","Услуги −$215 млн; текущий счёт −$173 млн"],"options_uz":["Xizmatlar −$35 mln; joriy hisob +$7 mln","Xizmatlar +$35 mln; joriy hisob +$77 mln","Xizmatlar −$35 mln; joriy hisob −$7 mln","Xizmatlar −$215 mln; joriy hisob −$173 mln"],"why":["Services =90−125=−35. Current account =50−35−10+2=+7 million.","Баланс услуг 90−125=−35. Текущий счёт 50−35−10+2=+7 млн.","Xizmatlar balansi 90−125=−35. Joriy hisob 50−35−10+2=+7 mln."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-041","d":"hard","sec":190,"k":"C","en":"A country''s goods balance is −$12bn and services balance +$5bn. Net primary income is +$1bn and net secondary income −$1bn. It plans to increase exports of goods without changing the other entries. By how much must goods exports rise to eliminate the current-account deficit?","ru":"Сальдо торговли товарами −$12 млрд, услугами +$5 млрд. Чистые первичные доходы +$1 млрд, вторичные −$1 млрд. Страна планирует увеличить экспорт товаров, не меняя остальные статьи. На сколько должен вырасти экспорт, чтобы устранить дефицит текущего счёта?","uz":"Mamlakat tovar balansi −$12 mlrd, xizmat balansi +$5 mlrd. Sof birlamchi daromad +$1 mlrd, ikkilamchi daromad −$1 mlrd. Boshqa bandlar o‘zgarmasa, joriy hisob taqchilligini yo‘qotish uchun tovar eksporti qancha oshishi kerak?","options_en":["$5bn","$12bn","$7bn","$6bn"],"options_ru":["$5 млрд","$12 млрд","$7 млрд","$6 млрд"],"options_uz":["$5 mlrd","$12 mlrd","$7 mlrd","$6 mlrd"],"why":["The current account equals −12+5+1−1=−7bn. All else fixed, extra goods exports of $7bn close the deficit.","Текущий счёт −12+5+1−1=−7 млрд; при неизменных остальных статьях нужен дополнительный экспорт на $7 млрд.","Joriy hisob −12+5+1−1=−7 mlrd; boshqalar o‘zgarmasa, eksport $7 mlrd ga oshishi kerak."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-044","d":"hard","sec":185,"k":"C","en":"Country A exports goods worth $145bn and imports $205bn; Country B exports $130bn and imports $175bn. Then A''s exports rise by $20bn, while B''s imports fall by $5bn, with all other flows unchanged. Which comparison is now correct?","ru":"Страна A экспортирует товаров на $145 млрд и импортирует на $205 млрд, страна B — на $130 и $175 млрд. Затем экспорт A растёт на $20 млрд, а импорт B сокращается на $5 млрд; остальные потоки неизменны. Как теперь сопоставляются торговые балансы?","uz":"A mamlakat tovarlarni $145 mlrd eksport va $205 mlrd import qiladi; B mamlakat $130 mlrd eksport va $175 mlrd import qiladi. Keyin A eksporti $20 mlrd oshadi, B importi $5 mlrd kamayadi; boshqa oqimlar o‘zgarmaydi. Savdo balanslari qanday bo‘ladi?","options_en":["A has a $15bn larger deficit","B has a $20bn larger deficit","Both have a $40bn goods-trade deficit","Both have a $45bn goods-trade deficit"],"options_ru":["Дефицит A больше на $15 млрд","Дефицит B больше на $20 млрд","У обеих стран дефицит товаров $40 млрд","У обеих стран дефицит товаров $45 млрд"],"options_uz":["A taqchilligi $15 mlrd ko‘proq","B taqchilligi $20 mlrd ko‘proq","Ikkalasida tovar savdosi taqchilligi $40 mlrd","Ikkalasida tovar savdosi taqchilligi $45 mlrd"],"why":["A initially −60bn and after export growth −40bn. B initially −45bn and after import reduction −40bn.","У A сначала −60, затем −40 млрд; у B сначала −45, затем −40 млрд. Дефициты сравнялись.","A da dastlab −60, keyin −40 mlrd; B da dastlab −45, keyin −40 mlrd. Taqchilliklar tenglashadi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-050","d":"hard","sec":180,"k":"A","en":"A $150,000 property can initially be mortgaged up to a 90% loan-to-value ceiling. The regulator lowers the ceiling to 75%. Assume the price is unchanged. By how much does the required minimum cash deposit rise, and what is the new maximum loan?","ru":"Жильё стоимостью $150 000 первоначально можно кредитовать до 90% его стоимости. Регулятор снижает допустимый LTV до 75%, цена жилья неизменна. На сколько вырастет минимальный первоначальный взнос и каков новый максимальный кредит?","uz":"Qiymati $150 000 bo‘lgan uyga avval 90% LTV chegarasida ipoteka olish mumkin edi. Regulyator chegara qiymatini 75% ga tushirdi, uy narxi o‘zgarmadi. Eng kam boshlang‘ich to‘lov qanchaga oshadi va yangi maksimal kredit qancha?","options_en":["Deposit +$22,500; loan $112,500","Deposit +$15,000; loan $135,000","Deposit +$37,500; loan $90,000","Deposit +$22,500; loan $135,000"],"options_ru":["Взнос +$22 500; кредит $112 500","Взнос +$15 000; кредит $135 000","Взнос +$37 500; кредит $90 000","Взнос +$22 500; кредит $135 000"],"options_uz":["Boshlang‘ich to‘lov +$22 500; kredit $112 500","Boshlang‘ich to‘lov +$15 000; kredit $135 000","Boshlang‘ich to‘lov +$37 500; kredit $90 000","Boshlang‘ich to‘lov +$22 500; kredit $135 000"],"why":["Old deposit =10%×150,000=$15,000; new deposit=25%×150,000=$37,500. Increase $22,500; loan=75%×150,000=$112,500.","Прежний взнос 10%×150 000=$15 000, новый 25%×150 000=$37 500. Прирост $22 500, кредит $112 500.","Eski to‘lov 10%×150 000=$15 000, yangi 25%×150 000=$37 500. Oshish $22 500; kredit $112 500."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-069","d":"hard","sec":180,"k":"D","en":"A bank quotes 1 US dollar = 13,000 som and 1 euro = 1.10 US dollars. A traveller buys €500. The bank charges an additional fixed 100,000 som transaction fee. Assuming these are the applicable rates, what total amount of som must the traveller pay?","ru":"Банк указывает курсы: 1 доллар США = 13 000 сумов; 1 евро = 1,10 доллара. Путешественник покупает €500. Банк дополнительно взимает фиксированную комиссию 100 000 сумов. Сколько сумов нужно заплатить при этих курсах?","uz":"Bank kurslari: 1 AQSH dollari = 13 000 so‘m; 1 yevro = 1,10 AQSH dollari. Sayohatchi €500 sotib oladi. Bank qo‘shimcha 100 000 so‘m qat’iy komissiya oladi. Shu kurslarda jami necha so‘m to‘lash kerak?","options_en":["6,600,000 som","7,150,000 som","7,050,000 som","7,250,000 som"],"options_ru":["6 600 000 сумов","7 150 000 сумов","7 050 000 сумов","7 250 000 сумов"],"options_uz":["6 600 000 so‘m","7 150 000 so‘m","7 050 000 so‘m","7 250 000 so‘m"],"why":["€500 × $1.10/€ = $550; $550 × 13,000 = 7,150,000 som; plus 100,000 som fee = 7,250,000 som.","€500 × $1,10 = $550; $550 × 13 000 = 7 150 000 сумов; плюс комиссия 100 000 = 7 250 000 сумов.","€500 × $1,10 = $550; $550 × 13 000 = 7 150 000 so‘m; ustiga 100 000 komissiya = 7 250 000 so‘m."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-004","d":"medium","sec":150,"k":"B","en":"Commercial banks have a $200m consumer-loan portfolio. The central bank cuts the maximum permitted one-year portfolio growth from 10% to 4%. If the original loan base stays fixed, how much less new lending is permitted, and what is the policy stance?","ru":"У банков портфель потребительских кредитов $200 млн. Центральный банк снижает предельный годовой рост портфеля с 10% до 4%. Если исходный объём кредитов неизменен, на сколько меньше новых кредитов теперь разрешено и каков характер политики?","uz":"Tijorat banklarining iste’mol kreditlari portfeli $200 mln. Markaziy bank bir yillik ruxsat etilgan o‘sish chegarasini 10% dan 4% ga tushirdi. Boshlang‘ich portfel o‘zgarmasa, yangi kreditlar qanchaga kamayadi va siyosat yo‘nalishi qanday?","options_en":["$8m; expansionary","$12m; contractionary","$20m; expansionary","$12m; expansionary"],"options_ru":["$8 млн; стимулирующая","$12 млн; сдерживающая","$20 млн; стимулирующая","$12 млн; стимулирующая"],"options_uz":["$8 mln; kengaytiruvchi","$12 mln; cheklovchi","$20 mln; kengaytiruvchi","$12 mln; kengaytiruvchi"],"why":["Previously up to $20m new credit was allowed; now only $8m. The reduction is $12m and restricts credit growth.","Ранее допускалось $20 млн новых кредитов, теперь $8 млн. Разница $12 млн; ограничение сдерживает рост кредитования.","Avval $20 mln yangi kreditga ruxsat, hozir $8 mln. Farq $12 mln; bu kredit o‘sishini cheklaydi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-013","d":"medium","sec":150,"k":"D","en":"A government initially spends $300m and receives $250m in revenue. To reduce demand-pull inflation it cuts purchases by $30m and raises taxes by $20m, with no other changes. What is its new budget balance and likely immediate effect on aggregate demand?","ru":"Государство первоначально расходует $300 млн и получает доходы $250 млн. Для снижения инфляции спроса оно сокращает закупки на $30 млн и повышает налоги на $20 млн. Каковы новое бюджетное сальдо и ожидаемый немедленный эффект на AD?","uz":"Davlat dastlab $300 mln sarflaydi va $250 mln daromad oladi. Talab inflyatsiyasini pasaytirish uchun xaridni $30 mln kamaytirib, soliqlarni $20 mln oshiradi. Yangi budjet saldosi va yalpi talabga dastlabki ta’siri qanday?","options_en":["$50m deficit; AD increases","$20m deficit; AD unchanged","$30m surplus; AD increases","Balanced budget; AD tends to fall"],"options_ru":["Дефицит $50 млн; AD растёт","Дефицит $20 млн; AD не меняется","Профицит $30 млн; AD растёт","Бюджет сбалансирован; AD имеет тенденцию к снижению"],"options_uz":["$50 mln taqchillik; AD oshadi","$20 mln taqchillik; AD o‘zgarmaydi","$30 mln profitsit; AD oshadi","Budjet muvozanatli; AD kamayishga intiladi"],"why":["New spending is $270m and revenue $270m, so the budget balances. Lower purchases and higher taxes tend to lower AD.","Новые расходы $270 млн и доходы $270 млн: бюджет сбалансирован. Снижение закупок и повышение налогов сдерживают AD.","Yangi xarajat va daromad $270 mln dan: budjet muvozanatda. Xaridlarni qisqartirish va soliqni oshirish AD ni pasaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-029","d":"medium","sec":150,"k":"C","en":"A central bank is concerned about accelerating demand-pull inflation. It sells government securities to banks, which pay from their reserves, and also raises its policy interest rate. Other influences are unchanged. Which combined transmission is most plausible?","ru":"Центральный банк обеспокоен ускорением инфляции спроса. Он продаёт банкам государственные бумаги, за которые те платят резервами, и одновременно повышает ключевую ставку. Прочие условия неизменны. Какой совместный механизм наиболее вероятен?","uz":"Markaziy bank talab inflyatsiyasi tezlashishidan xavotirda. U banklarga davlat qimmatli qog‘ozlarini sotadi, banklar zaxiralari hisobidan to‘laydi; ayni paytda siyosat stavkasi oshiriladi. Boshqa omillar o‘zgarmasa, qanday umumiy uzatish mexanizmi kutiladi?","options_en":["Bank reserves rise and credit becomes cheaper.","The government automatically collects more tariff revenue.","Bank reserves fall and borrowing becomes more expensive, restraining AD.","Long-run productive capacity immediately doubles."],"options_ru":["Банковские резервы растут, кредиты дешевеют.","Государство автоматически получает больше таможенных сборов.","Резервы банков падают, заимствования дорожают, сдерживая AD.","Долгосрочный производственный потенциал сразу удваивается."],"options_uz":["Bank zaxiralari oshib, kredit arzonlashadi.","Davlat avtomatik ko‘proq boj daromadi oladi.","Bank zaxiralari kamayib, qarz qimmatlashadi va AD cheklanadi.","Uzoq muddatli ishlab chiqarish quvvati darhol ikki baravar oshadi."],"why":["Selling securities withdraws bank reserves; higher rates discourage some borrowing and spending. Both are contractionary monetary channels.","Продажа бумаг изымает резервы; более высокая ставка сдерживает кредиты и расходы. Оба инструмента ограничивают денежные условия.","Qimmatli qog‘oz sotuvi bank zaxirasini kamaytiradi; yuqori stavka qarz va xarajatni cheklaydi. Ikkisi ham cheklovchi siyosatdir."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-032","d":"medium","sec":145,"k":"A","en":"Foreign investors exchange overseas money for Country R''s currency to buy its bonds. The exchange rate floats and other flows are initially fixed. Which pair of immediate currency-market pressure and potential export-competitiveness effect follows?","ru":"Иностранные инвесторы меняют валюту на деньги страны R для покупки её облигаций. Курс плавающий, прочие валютные потоки первоначально неизменны. Какая пара «давление на курс — возможный эффект на экспортную конкурентоспособность» следует?","uz":"Xorijiy investorlar R mamlakati obligatsiyalarini olish uchun xorijiy pulni R valutasiga almashtiradi. Kurs suzuvchi, boshqa valuta oqimlari dastlab o‘zgarmaydi. «Kursga bosim — eksport raqobatbardoshligiga ehtimoliy ta’sir» juftligi qaysi?","options_en":["Appreciation pressure; exports may become dearer to foreign buyers","Depreciation pressure; exports always become cheaper","Appreciation pressure; exports necessarily double","No exchange-rate pressure; exports are unaffected by currency values"],"options_ru":["Давление к укреплению; экспорт может подорожать для иностранцев","Давление к обесценению; экспорт всегда дешевеет","Укрепление; экспорт обязательно удвоится","Нет давления на курс; валютный курс не влияет на экспорт"],"options_uz":["Qadrlanish bosimi; eksport chet elliklar uchun qimmatlashishi mumkin","Qadrsizlanish bosimi; eksport har doim arzonlashadi","Qadrlanish bosimi; eksport albatta ikki baravar oshadi","Kursga bosim yo‘q; valuta eksportga ta’sir qilmaydi"],"why":["Demand for domestic currency rises, creating appreciation pressure; a stronger currency can make home exports more expensive abroad.","Национальная валюта становится более востребованной и может укрепиться; это способно повысить иностранную цену экспорта.","Mahalliy valutaga talab ko‘payib, qadrlanish bosimini yaratadi; kuchli valuta eksportni chet elliklar uchun qimmatlashtirishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-035","d":"medium","sec":165,"k":"B","en":"A country''s linear PPC allows either 20 computers or 80 tonnes of grain. It produces 20 computers, exports five, and imports 30 tonnes of grain in exchange. Which conclusion follows about its consumption bundle?","ru":"Линейная КПВ страны допускает выпуск либо 20 компьютеров, либо 80 тонн зерна. Страна производит 20 компьютеров, экспортирует пять и получает в обмен 30 тонн зерна. Какой вывод следует о её потребительском наборе?","uz":"Mamlakatning chiziqli ishlab chiqarish imkoniyatlari egri chizig‘i 20 kompyuter yoki 80 tonna don ishlab chiqarishga imkon beradi. Mamlakat 20 kompyuter ishlab chiqarib, beshtasini eksport qiladi va 30 tonna don import qiladi. Iste’mol to‘plami haqida qanday xulosa kelib chiqadi?","options_en":["The economy produces 15 computers and 30 tonnes of grain domestically.","Its consumption of 15 computers and 30 tonnes of grain lies outside its own PPC.","The import contract shifts its physical PPC inward.","Trade prevents consumption of any grain."],"options_ru":["Страна внутри себя производит 15 компьютеров и 30 тонн зерна.","Потребление 15 компьютеров и 30 тонн зерна находится за пределами её собственной КПВ.","Импортный контракт сдвигает физическую КПВ внутрь.","Торговля исключает потребление зерна."],"options_uz":["Mamlakat ichida 15 kompyuter va 30 tonna don ishlab chiqaradi.","15 kompyuter va 30 tonna don iste’moli o‘zining IIECsidan tashqarida joylashgan.","Import bitimi fizik IIECni ichkariga siljitadi.","Savdo don iste’molini imkonsiz qiladi."],"why":["The domestic linear PPC allows 20 tonnes of grain at 15 computers, whereas trade permits consumption of 30. Production stays on the PPC, consumption can lie beyond it.","На собственной КПВ при 15 компьютерах возможно лишь 20 тонн зерна, а благодаря обмену потребляется 30. Производство остаётся на КПВ, потребление выходит за неё.","Mahalliy IIECda 15 kompyuter bilan atigi 20 tonna don mumkin, savdo orqali 30 tonna iste’mol qilinadi. Ishlab chiqarish IIECda, iste’mol tashqarida."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-042","d":"medium","sec":155,"k":"C","en":"A worker pays 20% personal income tax on $20,000 taxable earnings, while a retailer charges 10% VAT on an item priced at $1,000 before VAT. Which pair correctly identifies the direct and indirect taxes and their amounts?","ru":"Работник платит подоходный налог 20% с облагаемого дохода $20 000; продавец начисляет НДС 10% на товар стоимостью $1 000 без налога. Какая пара правильно определяет прямой и косвенный налоги с суммами?","uz":"Ishchi $20 000 soliqqa tortiladigan daromaddan 20% shaxsiy daromad solig‘i to‘laydi; sotuvchi QQSsiz $1000 lik mahsulotga 10% QQS qo‘shadi. Qaysi juftlik to‘g‘ridan-to‘g‘ri va egri soliqlarni hamda summalarini to‘g‘ri ko‘rsatadi?","options_en":["Direct VAT $100; indirect income tax $4,000","Direct income tax $400; indirect VAT $1,000","Direct income tax $4,000; indirect VAT $100","Direct VAT $1,000; indirect income tax $2,000"],"options_ru":["Прямой НДС $100; косвенный подоходный $4 000","Прямой подоходный $400; косвенный НДС $1 000","Прямой подоходный $4 000; косвенный НДС $100","Прямой НДС $1 000; косвенный подоходный $2 000"],"options_uz":["To‘g‘ri QQS $100; egri daromad solig‘i $4000","To‘g‘ri daromad solig‘i $400; egri QQS $1000","To‘g‘ri daromad solig‘i $4000; egri QQS $100","To‘g‘ri QQS $1000; egri daromad solig‘i $2000"],"why":["Income tax is a direct tax: 0.20×20,000=$4,000. VAT is indirect: 0.10×1,000=$100.","Подоходный налог — прямой: 0,20×20 000=$4 000. НДС — косвенный: 0,10×1 000=$100.","Daromad solig‘i to‘g‘ri: 0,20×20 000=$4000. QQS egri: 0,10×1000=$100."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-048","d":"medium","sec":160,"k":"D","en":"An imported bicycle has a pre-tariff landed price of $200. A 15% ad valorem import duty is imposed. Assume 100 bicycles are imported and the entire duty is reflected in the domestic price, with no other charges. What are the new price per bicycle and government revenue?","ru":"Импортный велосипед стоит $200 с доставкой, но без пошлины. Вводится адвалорная пошлина 15%. Ввозят 100 велосипедов; пошлина полностью отражается в цене, других сборов нет. Найдите новую цену велосипеда и доход бюджета.","uz":"Import velosipedining bojdan oldingi yetib kelgan narxi $200. 15% advalor boj joriy etildi. 100 velosiped import qilinadi, boj to‘liq ichki narxda aks etadi, boshqa yig‘imlar yo‘q. Velosipedning yangi narxi va davlat daromadi qancha?","options_en":["$215; revenue $1,500","$230; revenue $15,000","$200; revenue $3,000","$230; revenue $3,000"],"options_ru":["$215; бюджет $1 500","$230; бюджет $15 000","$200; бюджет $3 000","$230; бюджет $3 000"],"options_uz":["$215; davlat $1500","$230; davlat $15 000","$200; davlat $3000","$230; davlat $3000"],"why":["Duty per bicycle =15%×$200=$30, raising price to $230. Revenue from 100 imports is $30×100=$3,000.","Пошлина с велосипеда 15%×$200=$30, цена $230. Доход бюджета $30×100=$3 000.","Har velosiped boji 15%×$200=$30, narx $230. Davlat daromadi $30×100=$3000."]},{"ref":"EC9708:G2:EC9708-G2-T3-P-063","d":"medium","sec":165,"k":"A","en":"An economy''s real GDP index increases from 100 to 106 while its population index rises from 100 to 102 over the same period. Approximately how much has real output per person increased, and which conclusion is justified?","ru":"Индекс реального ВВП вырос со 100 до 106, а индекс населения за тот же период — со 100 до 102. На сколько примерно вырос реальный выпуск на человека и какой вывод обоснован?","uz":"Bir davrda real YaIM indeksi 100 dan 106 ga, aholi indeksi 100 dan 102 ga oshdi. Jon boshiga real ishlab chiqarish qanchaga ko‘paydi va qanday xulosa asosli?","options_en":["+3.92%; average material output per person grew, but distribution is not established","+6%; all citizens'' incomes necessarily rose equally","+4%; unemployment necessarily fell to zero","+8%; environmental quality necessarily improved"],"options_ru":["+3,92%; средний реальный выпуск на человека вырос, но распределение неизвестно","+6%; доходы всех граждан обязательно выросли одинаково","+4%; безработица обязательно исчезла","+8%; экологическая ситуация обязательно улучшилась"],"options_uz":["+3,92%; jon boshiga o‘rtacha real ishlab chiqarish oshdi, lekin taqsimot noma’lum","+6%; barcha fuqarolar daromadi bir xil oshdi","+4%; ishsizlik albatta nolga tushdi","+8%; ekologik holat albatta yaxshilandi"],"why":["Per-person real output factor =1.06/1.02≈1.0392, or +3.92%. The average rises, but the data say nothing about income distribution.","Реальный выпуск на человека: 1,06/1,02≈1,0392, или +3,92%. Рост среднего не доказывает равномерность распределения доходов.","Jon boshiga real ishlab chiqarish: 1,06/1,02≈1,0392, ya’ni +3,92%. O‘rtacha o‘sish daromadlar teng taqsimlanganini bildirmaydi."]}]'::jsonb;
  item jsonb; v_old bigint; v_new bigint; v_pool bigint; v_order int; v_count int;
  v_correct text; v_i int; v_why_en text; v_why_ru text; v_why_uz text; v_old_key text;
  v_saved_answers int;
BEGIN
  IF jsonb_array_length(payload) <> 28 THEN RAISE EXCEPTION 'expected_28_replacements'; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l
    JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=3 AND l.is_active;
  IF v_count <> 70 THEN RAISE EXCEPTION 'T3_pool_not_70_before: %',v_count; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    v_old_key := item->>'ref'; v_correct := item->>'k';
    IF jsonb_array_length(item->'options_en')<>4 OR jsonb_array_length(item->'options_ru')<>4 OR jsonb_array_length(item->'options_uz')<>4 THEN
      RAISE EXCEPTION 'four_options_required: %',v_old_key;
    END IF;
    IF v_correct NOT IN ('A','B','C','D') OR item->>'d' NOT IN ('medium','hard') THEN RAISE EXCEPTION 'invalid_authoring: %',v_old_key; END IF;
    SELECT q.id INTO STRICT v_old FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=v_old_key;
    SELECT count(*) INTO v_saved_answers FROM public.practice_answers a WHERE a.question_id=v_old;
    IF v_saved_answers > 0 THEN RAISE EXCEPTION 'review_history_bearing_question_before_replacement: %',v_old_key; END IF;
    SELECT l.pool_id,l.order_no INTO STRICT v_pool,v_order FROM public.practice_pool_questions l
      JOIN public.practice_pools p ON p.id=l.pool_id
      WHERE l.question_id=v_old AND l.is_active AND p.subject_id=7 AND p.tour_no=3;
    SELECT id INTO v_new FROM public.questions WHERE subject_id=7 AND book_ref=v_old_key||'-V2';
    IF v_new IS NOT NULL THEN RAISE EXCEPTION 'already_exists: %',v_old_key; END IF;
    v_i := ascii(v_correct)-64;
    v_why_en := item->'why'->>0; v_why_ru := item->'why'->>1; v_why_uz := item->'why'->>2;
    INSERT INTO public.questions (
      subject_id,topic,subtopic,difficulty,qtype,
      question_text,options_text,correct_answer,explanation,image_url,is_active,
      question_text_ru,question_text_uz,question_text_en,
      options_text_ru,options_text_uz,options_text_en,
      explanation_ru,explanation_uz,explanation_en,
      book_ref,time_limit_sec,quality_flag,quality_status
    )
    SELECT
      src.subject_id,src.topic,src.subtopic,item->>'d','mcq',
      item->>'en',(item->'options_en')::text,v_correct,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      NULL,true,item->>'ru',item->>'uz',item->>'en',
      (item->'options_ru')::text,(item->'options_uz')::text,(item->'options_en')::text,
      'Правильный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nПочему: '||v_why_ru,
      'To‘g‘ri javob: '||(item->'options_uz'->>(v_i-1))||E'\nSabab: '||v_why_uz,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      v_old_key||'-V2',(item->>'sec')::int,src.quality_flag,'published'
    FROM public.questions src WHERE src.id=v_old
    RETURNING id INTO v_new;
    UPDATE public.practice_pool_questions SET is_active=false
      WHERE pool_id=v_pool AND question_id=v_old AND is_active;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>1 THEN RAISE EXCEPTION 'old_link_not_one: %',v_old_key; END IF;
    INSERT INTO public.practice_pool_questions (pool_id,question_id,order_no,is_active)
      VALUES (v_pool,v_new,v_order,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
      VALUES(v_old,v_new,'replacement','Economics Gen2: actual editorial difficulty upgrade, T3 governed practice, originals retained');
    FOR v_i IN 1..4 LOOP
      INSERT INTO public.question_answer_diagnostics(
        question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,
        next_action_ru,next_action_uz,next_action_en,rule_json,quality_status
      )
      SELECT v_new,'mcq_option',chr(64+v_i),NULL,(chr(64+v_i)=v_correct),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'multi_step_economic_reasoning' END,
        src.subtopic,
        'Выбранный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nОбъяснение: '||v_why_ru||E'\nПравильный ответ: '||(item->'options_ru'->>(ascii(v_correct)-65)),
        'Tanlangan javob: '||(item->'options_uz'->>(v_i-1))||E'\nIzoh: '||v_why_uz||E'\nTo‘g‘ri javob: '||(item->'options_uz'->>(ascii(v_correct)-65)),
        'Selected answer: '||(item->'options_en'->>(v_i-1))||E'\nReason: '||v_why_en||E'\nCorrect answer: '||(item->'options_en'->>(ascii(v_correct)-65)),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Повторите метод решения и проверьте каждый шаг.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Yechim usulini takrorlang va har bir bosqichni tekshiring.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Review the method and check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T3P'||substring(v_old_key from 'P-([0-9]{3})')||'_V2_'||chr(64+v_i)),
        'published'
      FROM public.questions src WHERE src.id=v_old;
    END LOOP;
  END LOOP;
  -- Existing unchanged T3 items receive academically reviewed metadata, not fabricated all-medium labels.
  UPDATE public.questions q SET difficulty=CASE
    WHEN right(q.book_ref,3) IN ('007','009','011','012','014','016','018','019','021','024','025','026','033','034','036','037','040','046','049','056','061','070') THEN 'medium'
    ELSE 'easy' END
    WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T3-P-[0-9]{3}$'
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(payload) j WHERE j->>'ref'=q.book_ref);
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>42 THEN RAISE EXCEPTION 'unchanged_count_expected42: %',v_count; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    WHERE p.subject_id=7 AND p.tour_no=3 AND l.is_active;
  IF v_count<>70 THEN RAISE EXCEPTION 'active_pool_not70_after: %',v_count; END IF;
  IF EXISTS (
    SELECT 1 FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
       JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=3 AND l.is_active
    GROUP BY 1 HAVING count(*)<>70
  ) THEN RAISE EXCEPTION 'pool_count_inconsistent'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=3 AND l.is_active AND q.difficulty='easy') <> 20
    THEN RAISE EXCEPTION 'difficulty_easy_not20'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=3 AND l.is_active AND q.difficulty='medium') <> 30
    THEN RAISE EXCEPTION 'difficulty_medium_not30'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=3 AND l.is_active AND q.difficulty='hard') <> 20
    THEN RAISE EXCEPTION 'difficulty_hard_not20'; END IF;
END $reb$;
COMMIT;
